+
+        @Override
+        public void flush() throws IOException {
+        }
+
+        @Override
+        public void close() throws IOException {
+        }
+      });
+    } catch (Throwable e) {
+      if (e instanceof Exception) {
+        handler.handle(new AsyncResult<Buffer>((Exception) e));
+      } else {
+        e.printStackTrace();
+      }
+      return;
+    }
+
+    handler.handle(new AsyncResult<Buffer>(buffer));
+  }
+
+}

