+    String responseSize = "-";
+    String contentLength = response.getHeaders().get(HttpHeaderConstants.CONTENT_LENGTH);
+    if (contentLength != null) {
+      responseSize = contentLength;
+    }
+
+    StringBuilder logLine = new StringBuilder()
+      .append(
