+                  read.release();
+                  complete(null);
+                } else {
+                  position += read.readableBytes();
+                  emitNext(read);
+                  if (position == stop) {
+                    complete(null);
+                  } else if (hasDemand()) {
+                    doRead();
+                  } else {
+                    reading.set(false);
+                    if (hasDemand()) {
