+    } else {
+      DefaultExecution.LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
+    }
+  }
+
+  @Override
+  public void complete() {
+    if (fire()) {
+      continuation.resume(downstream::complete);
+    } else {
+      DefaultExecution.LOGGER.error("", new OverlappingExecutionException("promise already fulfilled"));
+    }
+  }
+}

