+package ratpack.groovy.handling
+
+class GroovyWhenHandlerSpec extends BasicGroovyDslSpec {
+
+  def "can use groovy truth in condition for true"() {
+    when:
+    handlers {
+      route { 1 } {
+        get { render "true" }
+      }
+    }
+
+    then:
+    text == "true"
+  }
+
+  def "can use groovy truth in condition for false"() {
+    when:
+    handlers {
+      route { "" } {
+        get { render "true" }
+      }
+      get { render "false" }
+    }
+
+    then:
+    text == "false"
+  }
+
+  def "context is delegate for predicate"() {
+    when:
+    handlers {
+      prefix(":foo?") {
+        route { pathTokens.foo } {
+          all { render "true" }
+        }
+        all { render "false" }
+      }
+    }
+
+    then:
+    getText("") == "false"
+    getText("bar") == "true"
+  }
+
+}

